-- Development-only seed data for local D1.
-- Dates and values are generated by seed-data.ts so weekly comparisons stay current.

INSERT INTO measurements (
  id,
  date,
  weight_kg,
  body_fat_percentage,
  muscle_percentage,
  resting_metabolism_kcal,
  created_at,
  updated_at
)
VALUES
{{rows}}
ON CONFLICT(date) DO UPDATE SET
  weight_kg = excluded.weight_kg,
  body_fat_percentage = excluded.body_fat_percentage,
  muscle_percentage = excluded.muscle_percentage,
  resting_metabolism_kcal = excluded.resting_metabolism_kcal,
  updated_at = excluded.updated_at
WHERE measurements.id LIKE 'dev-seed:%';
